import React, { useEffect, useRef, useState } from 'react';
import ChatMessage from './components/ChatMessage';
import InputBar from './components/InputBar';
import { detectAdversarial, correctPrompt, queryLLM } from './services/api';

const App = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const bottomRef = useRef(null);

  const scrollToBottom = () => bottomRef.current?.scrollIntoView({ behavior: 'smooth' });

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const prompt = input.trim();
    setMessages((prev) => [...prev, { sender: 'user', text: prompt }]);
    setInput('');
    setIsLoading(true);

    try {
      const detection = await detectAdversarial(prompt);
      if (detection.isAdversarial) {
        setMessages((prev) => [...prev, { sender: 'bot', text: '🔒 Adversarial prompt detected. Correcting...' }]);
        const correction = await correctPrompt(prompt);
        setMessages((prev) => [...prev, { sender: 'bot', text: `✏️ Corrected Prompt:\n${correction.correctedPrompt}` }]);
        const llmRes = await queryLLM(correction.correctedPrompt);
        setMessages((prev) => [...prev, { sender: 'bot', text: llmRes.response }]);
      } else {
        const llmRes = await queryLLM(prompt);
        setMessages((prev) => [...prev, { sender: 'bot', text: llmRes.response }]);
      }
    } catch {
      setMessages((prev) => [...prev, { sender: 'bot', text: '❌ Something went wrong.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-gray-100 dark:bg-gray-900 transition-colors">
      <header className="text-center py-4 text-lg font-semibold bg-white dark:bg-gray-800 shadow-md text-gray-800 dark:text-white">
        Adversarial Chat Interface
      </header>

      <main className="flex-1 overflow-y-auto px-4 py-6">
        <div className="max-w-2xl mx-auto space-y-4">
          {messages.map((msg, idx) => (
            <ChatMessage key={idx} sender={msg.sender} text={msg.text} />
          ))}
          <div ref={bottomRef} />
        </div>
      </main>

      <footer className="bg-white dark:bg-gray-800 shadow-inner px-4 py-2">
        <InputBar value={input} onChange={(e) => setInput(e.target.value)} onSubmit={handleSend} isLoading={isLoading} />
      </footer>
    </div>
  );
};

export default App;
